 if not index.exists():
  need(not index.is_symlink(),'Dangling upload index alias refused');return []
 artifacts=out/'artifacts';obj=artifacts/'obj'
 for p in [index.parent,index,artifacts,obj]:
  need(not p.is_symlink() and p.resolve()==p,'Upload index/obj ancestor alias refused')
 need(index.is_file() and index.stat().st_size<=65536 and obj.is_dir(),'Bounded regular selected-assets index and obj required')
 data=json.loads(index.read_bytes());rows=data.get('rows');need(isinstance(rows,list) and rows and data.get('existingBodiesUploadedDirectly') is True,'Actual captured selected-assets rows required')
 paths=[];total=0
 for row in rows:
  relative=row.get('path');need(isinstance(relative,str) and relative.startswith('obj/') and relative.endswith('/project.assets.json') and '\n' not in relative and '\r' not in relative and '\\' not in relative,'Bounded canonical asset relative path required')
  p=artifacts/relative;need(p.is_file() and not p.is_symlink() and p.resolve()==p and p.is_relative_to(obj),'Regular contained upload asset required')
  for parent in p.parents:
   if parent==obj:break
   need(not parent.is_symlink(),'Upload asset ancestor alias refused')
  need(p.relative_to(artifacts).as_posix()==relative,'Upload asset path normalization refused')
  size=p.stat().st_size;need(type(row.get('bytes')) is int and size==row['bytes'] and size<=512*1024,'Exact bounded upload member size required')
  total+=size;need(total<=2*1024*1024,'Bounded selected upload total exceeded')
  need(sha(p)==row.get('sha256'),'Captured selected upload body changed');paths.append(p)
 current=sorted(obj.rglob('project.assets.json'))
 need(len(set(paths))==len(paths) and sorted(paths)==current and type(data.get('bodyBytes')) is int and total==data['bodyBytes'],'Exact selected upload body set/total required')
